SELECT COUNT(*)
FROM (
    SELECT match_id, inning, striker_id, SUM(runs_scored) AS inns_runs
    FROM Deliveries
    WHERE match_id IN (
        SELECT match_id FROM Matches WHERE strftime('%Y', start_date) = '2023'
    )
    GROUP BY match_id, inning, striker_id
    HAVING inns_runs >= 200
) AS double_centuries;

